using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
public static class C127CombatGeometry
{
    const string Dir="Assets/Blueprinter/Mods/Gunmageddon/C127/";
    static int Crossings(MeshFilter mesh,MeshCollider bunker){var vertices=mesh.sharedMesh.vertices;var triangles=mesh.sharedMesh.triangles;int hits=0;for(int i=0;i<triangles.Length;i+=3)for(int edge=0;edge<3;edge++){var from=mesh.transform.TransformPoint(vertices[triangles[i+edge]]);var to=mesh.transform.TransformPoint(vertices[triangles[i+(edge+1)%3]]);var d=to-from;RaycastHit hit;if(d.magnitude>.004f&&bunker.Raycast(new Ray(from+d.normalized*.002f,d.normalized),out hit,d.magnitude-.004f)&&hit.distance<d.magnitude-.004f)hits++;}return hits;}
    public static object Run(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");var scene=EditorSceneManager.NewPreviewScene();var findings=new List<object>();try{foreach(string suffix in new[]{"A","B","C"}){var root=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(Dir+"C127"+suffix+"_Emplacement.prefab"));SceneManager.MoveGameObjectToScene(root,scene);var bunker=root.transform.Find("BunkerStructure").GetComponent<MeshCollider>();foreach(var turret in root.GetComponentsInChildren<Turret>(true)){var rig=turret.transform.parent;var gun=turret.GetComponentInChildren<Gun>(true);var clip=rig.GetComponent<Animation>().clip;float ymax=suffix=="B"?20:suffix=="A"?10:15,pmax=suffix=="B"?15:8;foreach(float yaw in new[]{-ymax,0,ymax})foreach(float pitch in new[]{-5f,0,pmax})foreach(float phase in new[]{.05f,.24f,.34f,.475f,.55f,.77f,.89f,.98f}){turret.transform.localRotation=Quaternion.Euler(0,yaw,0);gun.transform.localRotation=Quaternion.Euler(-pitch,0,0);clip.SampleAnimation(rig.gameObject,phase*5.17f);Physics.SyncTransforms();foreach(var mesh in rig.GetComponentsInChildren<MeshFilter>(true).Where(m=>m.gameObject.activeInHierarchy&&!m.name.StartsWith("GM_LOD",StringComparison.Ordinal))){int hits=Crossings(mesh,bunker);if(hits>0)findings.Add(new{unit=suffix,mount=rig.name,yaw,pitch,phase,mesh=mesh.name,hits});}}}UnityEngine.Object.DestroyImmediate(root);}string json=Newtonsoft.Json.JsonConvert.SerializeObject(findings);var path=System.IO.Path.Combine((System.Environment.GetEnvironmentVariable("GUNMAGGEDON_ROOT") ?? throw new System.InvalidOperationException("Set GUNMAGGEDON_ROOT before running editor tools or fixtures.")), "UnitySetupBackup/C127/Validation/CombatGeometry.json");Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,json);return new{intersections=findings.Count,evidence=path,examples=findings.Take(12).ToArray(),note="Triangle-edge sweeps against own concrete, not a whole-volume penetration proof"};}finally{EditorSceneManager.ClosePreviewScene(scene);}}
}
